
#include <map>
struct E12PlayHead:juce::AudioPlayHead { bool playing=false;int64_t samples=0;double sr=48000;juce::Optional<PositionInfo> getPosition()const override{PositionInfo p;p.setIsPlaying(playing);p.setTimeInSamples(samples);p.setTimeInSeconds(samples/sr);return p;} };
static int testE12Stress(){
 const int count=std::getenv("E12_CYCLES")?std::atoi(std::getenv("E12_CYCLES")):208;std::mt19937 rng(120015);std::uniform_real_distribution<double> pause(.2,5.),x(-2.,16.),y(-1.,3.);double worst=0,worstRecovery=0;int silent=0,nonzero=0;
 auto rooms=verbp::builtinRooms();auto room=*std::find_if(rooms.begin(),rooms.end(),[](const auto&r){return r.name=="Corridor";});std::istringstream roomInput(room.text);auto authored=verb::parseScene(roomInput,"Corridor");
 const std::array<std::array<double,4>,8> poses{{{{1.5,1,11,1}},{{7,-1,10,1}},{{15.5,1,11,1}},{{11,1,15,1}},{{-1,1,3,1}},{{7,1.8,7,.03}},{{15,1,16,1}},{{7,-1,9,-1}}}};
 std::vector<float> signal(8192);std::mt19937 noise(1200);std::uniform_real_distribution<float> uniform(-.03f,.03f);for(auto&v:signal)v=uniform(noise);
 auto configure=[&](VerbProcessor& p,const std::string& text,double sr,int block){p.setPlayConfigDetails(2,2,sr,block);p.setTailSettings({8000,false});p.loadSceneText(text,"E12 Corridor",true);p.prepareToPlay(sr,block);check(waitReady(p,60),"E12 stress room ready");setP(p,"mode",1);setP(p,"mix",100);setP(p,"spatialDry",0);setP(p,"doppler",1);setP(p,"soloDirect",0);setP(p,"soloEarly",1);setP(p,"soloTail",1);};
 auto pose=[&](VerbProcessor& p,const std::array<double,4>& a){setP(p,"s1x",a[0]);setP(p,"s1y",a[1]);setP(p,"lx",a[2]);setP(p,"ly",a[3]);};
 auto process=[&](VerbProcessor& p,E12PlayHead& ph,int block,int blocks,bool bypass=false){juce::AudioBuffer<float> b(2,block);juce::MidiBuffer midi;double energy=0;for(int n=0;n<blocks;++n){for(int i=0;i<block;++i)b.setSample(0,i,signal[(size_t)(ph.samples+i)%signal.size()]);b.clear(1,0,block);if(bypass)p.processBlockBypassed(b,midi);else p.processBlock(b,midi);ph.samples+=block;for(int c=0;c<2;++c)for(int i=0;i<block;++i)energy+=(double)b.getSample(c,i)*b.getSample(c,i);}return energy/(2.*block*blocks);};
 auto settle=[&](VerbProcessor& p,E12PlayHead& ph,int block){auto start=std::chrono::steady_clock::now();do{process(p,ph,block,8);juce::MessageManager::getInstance()->runDispatchLoopUntil(3);}while((!p.isWebTailCurrent()||std::chrono::steady_clock::now()-start<std::chrono::milliseconds(700))&&std::chrono::steady_clock::now()-start<std::chrono::seconds(8));process(p,ph,block,(int)std::ceil(20*ph.sr/block));return std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();};
 for(int config=0;config<4;++config){auto sc=authored;sc.ceilingInfinite=(config&1)!=0;if(config>=2)sc.walls.erase(sc.walls.begin()+1);auto text=verb::serializeScene(sc);VerbProcessor p;E12PlayHead head;p.setPlayHead(&head);int block=256;configure(p,text,head.sr,block);std::map<std::pair<int,int>,std::array<double,2>> references;
 for(int rate:{48000,44100})for(int index=0;index<(int)poses.size();++index){VerbProcessor cold;E12PlayHead coldHead;coldHead.sr=rate;cold.setPlayHead(&coldHead);configure(cold,text,rate,256);pose(cold,poses[index]);coldHead.playing=true;settle(cold,coldHead,256);std::array<double,2> values{};for(int bus=0;bus<2;++bus){setP(cold,"soloEarly",bus==0);setP(cold,"soloTail",bus==1);process(cold,coldHead,256,(int)(rate/256));values[bus]=process(cold,coldHead,256,32);}references[{index,rate}]=values;}

 for(int cycle=config;cycle<count;cycle+=4){head.playing=false;const auto gapStart=std::chrono::steady_clock::now();const double gap=pause(rng);int changes=0;
 while(std::chrono::duration<double>(std::chrono::steady_clock::now()-gapStart).count()<gap){if(changes++%7==0){setP(p,"s1x",x(rng));setP(p,"s1y",y(rng));setP(p,"lx",x(rng));setP(p,"ly",y(rng));}juce::MessageManager::getInstance()->runDispatchLoopUntil(4);}
 const int index=(int)(rng()%poses.size());const auto lastChange=std::chrono::steady_clock::now();pose(p,poses[index]);if(cycle%13==0){head.sr=head.sr==48000?44100:48000;block=block==256?512:256;p.setPlayConfigDetails(2,2,head.sr,block);p.prepareToPlay(head.sr,block);check(waitReady(p,60),"E12 SR/block change ready");}
 head.playing=true;if(cycle%5==0)process(p,head,block,5,true);
 const auto key=std::make_pair(index,(int)head.sr);process(p,head,block,(int)std::ceil(20*head.sr/block));
 std::array<double,2> actuals{};bool matched=false;
 do{matched=true;for(int bus=0;bus<2;++bus){setP(p,"soloEarly",bus==0);setP(p,"soloTail",bus==1);process(p,head,block,(int)(head.sr/block));actuals[bus]=process(p,head,block,8192/block);const double reference=references[key][bus];matched&=reference>1e-14?std::abs(10*std::log10(std::max(1e-300,actuals[bus])/reference))<=1.:actuals[bus]<1e-12;}if(matched)break;juce::MessageManager::getInstance()->runDispatchLoopUntil(4);}while(std::chrono::steady_clock::now()-lastChange<std::chrono::seconds(8));
 const double recovery=std::chrono::duration<double>(std::chrono::steady_clock::now()-lastChange).count();worstRecovery=std::max(worstRecovery,recovery);check(matched&&recovery<=8.,"E12 actual wet recovery within8s wall time");
 for(int bus=0;bus<2;++bus){const double actual=actuals[bus],reference=references[key][bus];double error=0;if(reference>1e-14){++nonzero;error=10*std::log10(std::max(1e-300,actual)/reference);worst=std::max(worst,std::abs(error));if(actual<reference*1e-6)++silent;check(std::abs(error)<=1.,"E12 resumed wet bus within1dB of cold static processor");}else check(actual<1e-12,"E12 zero cold reference has no stale wet signal");printf("E12_STRESS cycle%d config%d pose%d bus%d gap%.3f sr%.0f block%d actual%.12g reference%.12g error_db%.6f recovery_s%.3f current%d\n",cycle,config,index,bus,gap,head.sr,block,actual,reference,error,recovery,p.isWebTailCurrent());}
 setP(p,"soloEarly",1);setP(p,"soloTail",1);
 }p.setPlayHead(nullptr);}
 printf("E12_STRESS SUMMARY cycles%d max_db%.6f max_recovery_s%.3f nonzero_refs%d silent%d failures%d\n",count,worst,worstRecovery,nonzero,silent,fails);return fails?1:0;
}
